    "name": "Slug",
    "spec": "module Slug version \"1\" {\n    target { language = Python; }\n\n    description = \"A URL slug maker. [C1] src/slug.py defines slugify(text: str, max_length: int = 60) -> str. [C2] The result holds only lowercase ASCII letters, digits and single hyphens, with no hyphen at either end. [C3] Accented Latin letters become their base letter (é is e, Ü is u); any other character that is not an ASCII letter or digit separates words. [C4] Words are joined by one hyphen: 'Hello,  World!' is 'hello-world'. [C5] A slug longer than max_length is cut to at most max_length characters at a word boundary, dropping the partial word and the hyphen before it; a first word longer than max_length is cut at max_length. [C6] Text with no ASCII letter or digit gives the empty string. [C7] text that is not a str raises TypeError; max_length that is not an int of at least 1 (a bool is not one) raises ValueError. [C8] The standard library only: unicodedata and re.\";\n\n    artifacts {\n        file \"src/slug.py\";\n    }\n\n    evaluate \"contract-v1\" {\n        hard shape = Exports(\"src/slug.py\", [\"slugify\"]);                       // [C1]\n        hard dependencies = Imports(\"src/**\", allow = [\"unicodedata\", \"re\"]);   // [C8]\n        hard behavior = Tests(\"tests/test_slug.py\", timeout = 30s);\n    }\n}\n",
    "flow": "implement Slug using \"contract-v1\" {\n    limit iterations 6, time 20m, cost 0usd;\n    policy = \"local-files-v1\";\n\n    available = await models.list(provider = \"llamacpp\");\n    selected = models.select(available, max_size = 6GiB, prefer = \"coder\");\n    developer = await models.load(selected);\n\n    spec = freeze(Slug.spec);\n    candidate = checkout(\"slug\");\n    feedback = none;\n\n    while (!accepted(candidate, spec)) {\n        candidate = await developer.revise(candidate, spec, feedback, file = \"src/slug.py\", format = \"source\");\n        evidence = await evaluate(candidate, spec, keep = \"best\");\n        verdict = verify(spec, evidence);\n        checkpoint(candidate, evidence, verdict);\n\n        if (verdict.status == Pass) {\n            return accept(candidate, evidence);\n        }\n        if (verdict.status == Unknown) {\n            return needs_review(evidence);\n        }\n        feedback = verdict.violations;\n    }\n    return unresolved();\n}\n",
    "tests": {
      "tests/test_slug.py": "import unittest\n\nfrom src.slug import slugify\n\n\nclass SlugTest(unittest.TestCase):\n    def test_c2_c4_joins_words_with_single_hyphens(self):\n        \"\"\"[C2][C4] words are joined by one hyphen, none at either end\"\"\"\n        self.assertEqual(slugify(\"Hello,  World!\"), \"hello-world\")\n        self.assertEqual(slugify(\"  --Already--slugged--  \"), \"already-slugged\")\n        self.assertEqual(slugify(\"Version 2.0 is OUT\"), \"version-2-0-is-out\")\n\n    def test_c3_accents_become_base_letters(self):\n        \"\"\"[C3] accented Latin letters lose their accents; other letters separate words\"\"\"\n        self.assertEqual(slugify(\"Crème Brûlée\"), \"creme-brulee\")\n        self.assertEqual(slugify(\"naïve Ünïcode café\"), \"naive-unicode-cafe\")\n        self.assertEqual(slugify(\"Привет мир 2\"), \"2\")\n\n    def test_c5_cuts_at_a_word_boundary(self):\n        \"\"\"[C5] a long slug is cut at a word boundary, a long first word at max_length\"\"\"\n        self.assertEqual(slugify(\"the quick brown fox\", max_length=12), \"the-quick\")\n        self.assertEqual(slugify(\"the quick\", max_length=9), \"the-quick\")\n        self.assertEqual(slugify(\"ab cd\", max_length=3), \"ab\")\n        self.assertEqual(slugify(\"supercalifragilistic\", max_length=5), \"super\")\n        self.assertEqual(len(slugify(\"word \" * 40)), 59)\n\n    def test_c6_nothing_to_keep_gives_empty(self):\n        \"\"\"[C6] no ASCII letter or digit gives the empty string\"\"\"\n        self.assertEqual(slugify(\"\"), \"\")\n        self.assertEqual(slugify(\"!!! --- ???\"), \"\")\n\n    def test_c7_rejects_wrong_arguments(self):\n        \"\"\"[C7] wrong types and lengths raise\"\"\"\n        with self.assertRaises(TypeError):\n            slugify(None)\n        with self.assertRaises(TypeError):\n            slugify(b\"bytes\")\n        for length in (0, -1, 2.5, True):\n            with self.assertRaises(ValueError):\n                slugify(\"text\", max_length=length)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
    },
    "frozen": {}
