    "spec": "module AbilitySystem version \"1\" {\n    target { language = Cpp; }\n\n    description = \"An engine-agnostic ability system core in C++20, in the spirit of Unreal's Gameplay Ability System. Implement every member of lc::AbilitySystem declared in the frozen include/AbilitySystem.h, in src/AbilitySystem.cpp, which includes \\\"AbilitySystem.h\\\" and the standard library only. TryActivate checks, in order: the ability is granted, it is off cooldown (now is in seconds; ready again when now >= the time of the last activation plus cooldownSeconds), the owner has none of the spec's blockedBy tags, mana is at least the cost, the target's health is above 0. The first failed check is returned and nothing changes. On success the cost is paid once, the cooldown starts and the spec's damage is applied to the target through ApplyDamage. Granting an id again replaces its spec and clears its cooldown. Health and mana always stay within [0, max]. The core is deterministic: no clocks, randomness, threads or I/O.\";\n\n    artifacts {\n        // Written by the engineer and frozen: the model reads it, never changes it.\n        frozen \"include/AbilitySystem.h\";\n        file \"src/AbilitySystem.cpp\";\n    }\n\n    evaluate \"contract-v1\" {\n        hard implementation = Exports(\"src/AbilitySystem.cpp\", [\"AbilitySystem::TryActivate\", \"AbilitySystem::Grant\", \"AbilitySystem::CooldownRemaining\", \"AbilitySystem::ApplyDamage\", \"AbilitySystem::RestoreMana\"]);\n        hard layering = Imports(\"src/**\", allow = [\"AbilitySystem.h\", \"include/AbilitySystem.h\", \"<*>\"], deny = [\"<thread>\", \"<random>\", \"<chrono>\", \"<ctime>\", \"<iostream>\", \"<fstream>\"]);\n        hard deterministic = Forbid(\"src/**\", \"\\\\b(s?rand|time|printf|puts)\\\\s*\\\\(|std::(cout|cerr|chrono)\", message = \"the core takes time from the caller and does no I/O\");\n        hard behavior = Tests(\"tests/ability_system_test.cpp\", timeout = 60s);\n    }\n}\n",
    "flow": "implement AbilitySystem using \"contract-v1\" {\n    limit iterations 8, time 30m, cost 0usd;\n    policy = \"local-files-v1\";\n\n    available = await models.list(provider = \"llamacpp\");\n    selected = models.select(available, max_size = 10GiB, prefer = \"coder\");\n    developer = await models.load(selected);\n\n    spec = freeze(AbilitySystem.spec);\n    candidate = checkout(\"ability-system\");\n    feedback = none;\n\n    while (!accepted(candidate, spec)) {\n        // The prompt carries the contract, the frozen header, the engineer's tests and the last\n        // failures (each with file:line, expected and actual).\n        candidate = await developer.revise(candidate, spec, feedback, file = \"src/AbilitySystem.cpp\", format = \"source\");\n        evidence = await evaluate(candidate, spec);\n        verdict = verify(spec, evidence);\n        checkpoint(candidate, evidence, verdict);\n\n        if (verdict.status == Pass) {\n            return accept(candidate, evidence);\n        }\n        if (verdict.status == Unknown) {\n            return needs_review(evidence);\n        }\n        feedback = verdict.violations;\n    }\n    return unresolved();\n}\n",
